import{Q as e,V as t,ht as n,nt as r,rt as i,tt as a}from"./chunks/framework.CieOZLr0.js";import"./chunks/assets.B_88IXSw.js";var o=JSON.parse(`{"title":"Content Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guides/content-settings.md","filePath":"guides/content-settings.md","lastUpdated":1785753401000}`),s={name:`guides/content-settings.md`};function c(t,o,s,c,l,u){return n(),a(`div`,null,[...o[0]||=[r(`<h1 id="content-settings" tabindex="-1">Content Settings <a class="header-anchor" href="#content-settings" aria-label="Permalink to “Content Settings”">​</a></h1><p>Content Settings will cause the cover of titles to be blurred and have a letter on them.</p><div align="center"><img src="/v0.9/content-settings-blurred-with-u-m.avif" alt="Blurred Covers" width="300"></div><h2 id="rating-indicators" tabindex="-1">Rating Indicators <a class="header-anchor" href="#rating-indicators" aria-label="Permalink to “Rating Indicators”">​</a></h2><p>There are three letters that may appear on the blurred covers:</p><ul><li><strong>A</strong> for Adult</li><li><strong>M</strong> for Mature</li><li><strong>U</strong> for Unknown</li></ul><h2 id="enabling-content-settings" tabindex="-1">Enabling Content Settings <a class="header-anchor" href="#enabling-content-settings" aria-label="Permalink to “Enabling Content Settings”">​</a></h2><p>To gain access to the Content Settings in Paperback, first you need to enable them on your device system settings.</p><h3 id="ios-ipados" tabindex="-1">iOS/iPadOS <a class="header-anchor" href="#ios-ipados" aria-label="Permalink to “iOS/iPadOS”">​</a></h3><ol><li>Go to the <strong>Settings</strong> app.</li><li>Tap <strong><em>Apps</em></strong> → <strong><em>Paperback</em></strong>.</li><li>Toggle on the <strong><em>Content Settings</em></strong> setting.</li></ol>`,10),e(`div`,{align:`center`},[e(`img`,{src:`/v0.9/content-settings-device-apps.avif`,alt:`Device Apps`,width:`300`,height:`100`,hspace:`10`}),i(),e(`img`,{src:`/v0.9/content-settings-enable-content-settings.avif`,alt:`Paperback App Settings`,width:`300`,height:`100`,hspace:`10`})],-1),r(`<h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h3><ol><li>In the menu bar at the top of the screen.</li><li>Select <strong><em>Paperback</em></strong> → <strong><em>Settings</em></strong> → <strong><em>General</em></strong>.</li><li>Enable the <strong><em>Content Settings</em></strong> setting.</li></ol><h2 id="app-configuration" tabindex="-1">App Configuration <a class="header-anchor" href="#app-configuration" aria-label="Permalink to “App Configuration”">​</a></h2><p>Once enabled on your device, two new sections for content settings will appear in the Paperback app.</p><ol><li>Tap the <em>cog icon</em> → <strong><em>General Settings</em></strong>.</li><li>Locate the new sections: <ul><li><strong>Library Content Settings</strong></li><li><strong>Search Content Settings</strong></li></ul></li></ol><p>These allow you to disable the blur on covers as well as to force hide titles instead.</p><div align="center"><img src="/v0.9/content-settings-content-settings-in-paperback.avif" alt="Content Settings in Paperback" width="300"></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Some extensions have their own Content Settings as well. See the <a href="/faq#specific-extensions">Specific Extensions FAQ</a> entries for more info.</p></div>`,8)]])}var l=t(s,[[`render`,c]]);export{o as __pageData,l as default};